<?php
ini_set('display_errors', 0);
error_reporting(E_ALL);

session_set_cookie_params([
    'lifetime' => 0,
    'path' => '/',
    'secure' => !empty($_SERVER['HTTPS']),
    'httponly' => true,
    'samesite' => 'Lax',
]);
session_start();

$uid = (int)($_SESSION['user_id'] ?? 0);
if (empty($_SESSION['logged_in']) || $uid <= 0) {
    header('Location: login');
    exit;
}

require_once 'db.php';
require_once 'theme.php';

if (empty($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}

$error = '';
$success = '';
$user = null;
$isGoogleOnly = false;

try {
    $stmt = $pdo->prepare('SELECT id, username, email, display_name, password, google_sub FROM users WHERE id = ? LIMIT 1');
    $stmt->execute([$uid]);
    $user = $stmt->fetch(PDO::FETCH_ASSOC);

    if (!$user) {
        session_unset();
        session_destroy();
        header('Location: login');
        exit;
    }

    // Accounts created via Google have no password: nothing to change here
    $isGoogleOnly = empty($user['password']);

    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $csrfToken = $_POST['csrf_token'] ?? '';
        $currentPassword = $_POST['current_password'] ?? '';
        $newPassword = $_POST['new_password'] ?? '';
        $confirmPassword = $_POST['confirm_password'] ?? '';

        if (!is_string($csrfToken) || !hash_equals($_SESSION['csrf_token'], $csrfToken)) {
            $error = 'Die Anfrage ist abgelaufen. Bitte laden Sie die Seite neu und versuchen Sie es erneut.';
        } elseif ($isGoogleOnly) {
            // Server-side block, even if someone sends the form manually
            $error = 'Dieses Konto verwendet die Google-Anmeldung. Das Passwort wird bei Google verwaltet.';
        } elseif (!is_string($currentPassword) || !password_verify($currentPassword, $user['password'])) {
            $error = 'Das aktuelle Passwort ist nicht korrekt.';
        } elseif (!is_string($newPassword) || strlen($newPassword) < 12) {
            $error = 'Das neue Passwort muss mindestens 12 Zeichen lang sein.';
        } elseif (strlen($newPassword) > 72) {
            $error = 'Das neue Passwort darf höchstens 72 Bytes lang sein.';
        } elseif ($newPassword !== $confirmPassword) {
            $error = 'Die neuen Passwörter stimmen nicht überein.';
        } elseif (password_verify($newPassword, $user['password'])) {
            $error = 'Das neue Passwort muss sich vom aktuellen Passwort unterscheiden.';
        } else {
            $newHash = password_hash($newPassword, PASSWORD_DEFAULT);
            $update = $pdo->prepare('UPDATE users SET password = ? WHERE id = ?');
            $update->execute([$newHash, $uid]);
            session_regenerate_id(true);
            $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
            $success = 'Ihr Passwort wurde geändert.';
        }
    }
} catch (PDOException $e) {
    error_log($e->getMessage());
    $error = 'Das Profil konnte momentan nicht geladen werden. Bitte versuchen Sie es später erneut.';
}

$username = (string)($user['username'] ?? ($_SESSION['username'] ?? ''));
$email = (string)($user['email'] ?? '');
$displayName = (string)($user['display_name'] ?? '');
$hasGoogle = !empty($user['google_sub']);

// Subscription plan (separate query so the profile still loads before the column exists)
$planLabels = ['free' => 'Gratis (ohne KI)', 'ai' => 'KI (ohne Bildgenerierung)', 'ai_full' => 'KI Plus (mit Bildgenerierung)'];
$subscription = 'free';
try {
    $planStmt = $pdo->prepare('SELECT subscription FROM users WHERE id = ? LIMIT 1');
    $planStmt->execute([$uid]);
    $planValue = (string)$planStmt->fetchColumn();
    if (isset($planLabels[$planValue])) {
        $subscription = $planValue;
    }
} catch (Throwable $e) {
    error_log('Subscription lookup failed: ' . $e->getMessage());
}

// Level brain for the title: same levels as on the main page
$levelNames = ['Novize', 'Praktiker', 'Fortgeschrittener', 'Experte', 'Kenner', 'Spezialist', 'Meister', 'Virtuose'];
$levelMins = [500, 1300, 2500, 4000, 6000, 8000, 10000, 15000];
$levelThumbs = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
];
$aktivaCount = 0;
try {
    $cnt = $pdo->prepare("SELECT COUNT(*) FROM meine_wortschatz WHERE user_id = ? AND Status = 'aktiva'");
    $cnt->execute([$uid]);
    $aktivaCount = (int)$cnt->fetchColumn();
} catch (PDOException $e) {
    error_log($e->getMessage());
}
$levelIdx = -1;
foreach ($levelMins as $i => $min) {
    if ($aktivaCount >= $min) $levelIdx = $i;
}

function e(string $s): string {
    return htmlspecialchars($s, ENT_QUOTES, 'UTF-8');
}
